pub type Article = { title: Str; content: Str; }

impl AsRef[Str] for Article {
  fn as_ref(self: &Article) -> &Str { return &self.title; }
}

fn print_title[T: AsRef[Str]](item: &T) {
  io.println("Title: " + item.as_ref());
}

fn main() -> Int {
  let a = Article{ title: "XIOM Guide", content: "Learn XIOM..." };
  let title: &Str = a.as_ref();
  return title.len();
}
